// Packed Q31 complex word of one stage twiddle: imaginary in bits 63..32,
// real in bits 31..0. Returns std::nullopt outside the frozen table so
// every consumer fails closed instead of extrapolating.
inline std::optional<uint64_t> getPackedQ31TwiddleBits(Q31TwiddleDirection direction, int64_t size,
                                                       int64_t index) {
  if (size < 2 || size > kMaxQ31TwiddleExtent || index < 0 || index >= size / 2)
    return std::nullopt;
  const Q31TwiddleComponents &entry = direction == Q31TwiddleDirection::Forward
                                          ? kForwardQ31Twiddles[size / 2 + index]
                                          : kInverseQ31Twiddles[size / 2 + index];
  return (static_cast<uint64_t>(static_cast<uint32_t>(entry.imaginary)) << 32) |
         static_cast<uint64_t>(static_cast<uint32_t>(entry.real));
}

